        if event["tenant"] != tenant:
            continue
        key = event["key"]
        current = winners.get(key)
        if current is None or (
            event["revision"], event["position"]
        ) > (current["revision"], current["position"]):
            winners[key] = event
    return {
        key: event["value"]
        for key, event in winners.items()
        if event["op"] == "put"
    }
","explanation":"Tracks the greatest (revision, position) event for each key in the requested tenant, retaining deletes during selection so older puts cannot resurrect keys. Only winning puts appear in the result. Input order does not matter, and inputs are not mutated. Expected time is O(n), with O(k) auxiliary space for k matching keys."}

{"answer":"def build_plan(targets, deps):
    import heapq

    if not targets:
        return []

    reachable = set()
    stack = []

    for target in targets:
        if target not in deps:
            raise ValueError("missing target")
        if target not in reachable:
            reachable.add(target)
            stack.append(target)

    while stack:
        task = stack.pop()
        for prerequisite in deps[task]:
            if prerequisite not in deps:
                raise ValueError("missing prerequisite")
            if prerequisite not in reachable:
                reachable.add(prerequisite)
                stack.append(prerequisite)

    indegree = {task: 0 for task in reachable}
    dependents = {task: [] for task in reachable}

    for task in reachable:
        prerequisites = set(deps[task])
        indegree[task] = len(prerequisites)
        for prerequisite in prerequisites:
            dependents[prerequisite].append(task)

    available = [task for task in reachable if indegree[task] == 0]
    heapq.heapify(available)
    result = []

    while available:
        task = heapq.heappop(available)
        result.append(task)
        for dependent in dependents[task]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(available, dependent)

    if len(result) != len(reachable):
        raise ValueError("reachable cycle")

    return result
","explanation":"First discovers only tasks reachable from the requested targets, validating missing names during that traversal. It then applies Kahn’s topological sort with a heap so the smallest available name is always selected. Duplicate prerequisites are collapsed as duplicate edges, and a short result detects reachable cycles. Unreachable graph defects are never examined."}

{"answer":"from heapq import heapify, heappop, heappush


def build_plan(targets, deps):
    prerequisites = {}
    stack = list(targets)
    while stack:
        task = stack.pop()
        if task in prerequisites:
            continue
        if task not in deps:
            raise ValueError('Missing task: ' + task)
        parents = set(deps[task])
        prerequisites[task] = parents
        stack.extend(parents)

    indegree = {task: len(parents)
                for task, parents in prerequisites.items()}
    dependents = {task: [] for task in prerequisites}
    for task, parents in prerequisites.items():
        for parent in parents:
            dependents[parent].append(task)

    available = [task for task, count in indegree.items() if count == 0]
    heapify(available)
    result = []
    while available:
        task = heappop(available)
        result.append(task)
        for dependent in dependents[task]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heappush(available, dependent)

    if len(result) != len(prerequisites):
        raise ValueError('Cycle in requested prerequisite closure')
    return result
","explanation":"An iterative traversal collects only the requested prerequisite closure, validates reachable names, and deduplicates prerequisites without modifying either input. Kahn’s algorithm uses a min-heap to select the lexicographically smallest available task at every step. Unprocessed closure tasks indicate a reachable cycle. Unrelated graph entries are never inspected, and empty targets naturally return an empty list. Runtime is O(T + V + E + V log V), where T counts target entries and V and E cover reachable tasks and prerequisite entries; auxiliary space is O(T + V + E)."}
